        return "Meow"

alt:
class Animal:
    def __init__(self, name):
        self.name = name

    def speak(self):
        return "..."


class Dog(Animal):
    sound = "Woof"

    def speak(self):
        return self.sound


class Cat(Animal):
    sound = "Meow"

    def speak(self):
        return self.sound
